<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Radish - Food for the future of work</title>
    <style>
        :root {
            --color-green: #b8e994;
            --color-pink: #f0b4e6;
            --color-yellow: #e8ea5d;
            --color-coral: #ff7e7e;
            --color-cream: #fdfbf7;
            --color-lime: #dbe885; /* Lighter green/yellow */
            --color-dark-green: #0a3d2e;
            --font-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-main);
            color: #333;
            overflow-x: hidden;
            background-color: #fff;
        }

        /* Utility */
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
            position: relative;
            z-index: 2;
        }

        .flex-center {
            display: flex;
            justify-content: center;
            align-items: center;
        }

        /* Wave Separator */
        .wave-separator {
            position: relative;
            width: 100%;
            height: 30px;
            line-height: 0;
            overflow: visible;
            z-index: 10;
        }

        .wave-separator svg {
            display: block;
            width: 100%;
            height: 100%;
        }

        /* --- HEADER / HERO SECTION (Green) --- */
        header.hero-section {
            background-color: var(--color-green);
            padding-top: 40px;
            text-align: center;
            position: relative;
            min-height: 600px;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            overflow: hidden;
        }

        nav {
            width: 100%;
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 15px 40px;
            position: absolute;
            top: 0;
            left: 0;
            color: #333;
            font-size: 14px;
            font-weight: 500;
        }

        .logo {
            font-size: 24px;
            font-weight: bold;
            letter-spacing: -1px;
            display: flex;
            align-items: center;
            gap: 5px;
        }
        .logo svg { width: 24px; height: 24px; fill: currentColor; }

        .nav-links {
            display: flex;
            gap: 25px;
        }

        .hero-content {
            margin-top: 80px;
            z-index: 2;
        }

        .hero-title-box {
            background: white;
            display: inline-block;
            padding: 12px 24px;
            border-radius: 4px;
            box-shadow: 0 4px 10px rgba(0,0,0,0.05);
            margin-bottom: 10px;
        }

        h1 {
            font-size: 42px;
            font-weight: 400;
            line-height: 1.1;
            color: #222;
            max-width: 500px;
            text-align: left;
        }

        .hero-image-container {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -60%);
            width: 700px;
            height: 450px;
            z-index: 1;
            pointer-events: none;
        }

        .hero-image-container img {
            width: 100%;
            height: 100%;
            object-fit: contain;
            filter: drop-shadow(0 10px 20px rgba(0,0,0,0.15));
        }

        .tagline-bar {
            width: 100%;
            background-color: var(--color-yellow);
            padding: 15px 0;
            display: flex;
            justify-content: center;
            gap: 30px;
            font-size: 14px;
            font-weight: 600;
            color: #222;
            flex-wrap: wrap;
            position: absolute;
            bottom: 0;
            z-index: 3;
        }


        /* --- CARDS SECTION (Pink) --- */
        section.cards-section {
            background-color: var(--color-pink);
            padding: 60px 0 120px 0; /* Extra bottom padding for wave overlap */
            position: relative;
        }

        .cards-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 30px;
            max-width: 1100px;
            margin: 0 auto;
        }

        .card {
            position: relative;
            border-radius: 30px;
            overflow: hidden;
            aspect-ratio: 1/1.1;
            box-shadow: 0 10px 25px rgba(0,0,0,0.05);
            transition: transform 0.3s ease;
        }

        .card:hover {
            transform: translateY(-5px);
        }

        .card img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .card-label {
            position: absolute;
            top: 15px;
            left: 15px;
            background: white;
            padding: 8px 16px;
            border-radius: 6px;
            font-weight: 600;
            font-size: 16px;
            box-shadow: 0 2px 5px rgba(0,0,0,0.1);
        }


        /* --- YELLOW STRIP --- */
        .yellow-strip {
            background-color: var(--color-yellow);
            height: 350px;
            width: 100%;
            position: relative;
        }

        /* --- CORAL STRIP --- */
        .coral-strip {
            background-color: var(--color-coral);
            height: 300px;
            width: 100%;
            position: relative;
        }

        /* --- CREAM STRIP --- */
        .cream-strip {
            background-color: var(--color-cream);
            height: 400px;
            width: 100%;
            position: relative;
        }

        /* --- LIME STRIP --- */
        .lime-strip {
            background-color: var(--color-lime);
            height: 350px;
            width: 100%;
            position: relative;
        }

        /* --- PINK STRIP 2 --- */
        .pink-strip-2 {
            background-color: var(--color-pink);
            height: 250px;
            width: 100%;
            position: relative;
        }

        /* --- FORM SECTION (Yellow) --- */
        section.form-section {
            background-color: var(--color-yellow);
            padding: 80px 0 140px 0;
            display: flex;
            justify-content: center;
            align-items: center;
            position: relative;
        }

        .contact-form {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px 40px;
            max-width: 600px;
            width: 100%;
        }

        .form-group label {
            display: block;
            font-size: 13px;
            font-weight: 600;
            margin-bottom: 8px;
            color: #222;
        }

        .form-group input {
            width: 100%;
            padding: 12px;
            border: none;
            border-radius: 8px;
            background: transparent;
            border-bottom: 2px solid rgba(0,0,0,0.1);
            font-family: inherit;
            outline: none;
        }

        .form-group input:focus {
            border-bottom-color: #333;
        }

        .form-full {
            grid-column: span 2;
        }

        .submit-btn {
            grid-column: span 2;
            justify-self: start;
            background-color: #eab8eb;
            color: #222;
            border: none;
            padding: 12px 28px;
            border-radius: 25px;
            font-weight: 600;
            cursor: pointer;
            transition: background 0.2s;
            margin-top: 10px;
        }

        .submit-btn:hover {
            background-color: #df9edf;
        }

        /* --- FOOTER (Dark Green) --- */
        footer {
            background-color: var(--color-dark-green);
            height: 150px;
            width: 100%;
        }

    </style>
</head>
